// 递减循环 for (int i = 10; i > 0; i--) { printf("%d
", i); // 10, 9, 8, ..., 1 } // 步长为 2 for (int i = 0; i < 10; i += 2) { printf("%d
", i); // 0, 2, 4, 6, 8 } // 多个变量 for (int i = 0, j = 10; i < j; i++, j--) { printf("i=%d, j=%d
", i, j); } // 省略某些部分（均合法，但不能省略分号） int i = 0; for (; i < 10; i++) { ... } // 初始化在循环外完成 for (int i = 0; i < 10; ) { // 更新在循环体内完成 printf("%d
", i); i++; } for (;;) { // 无限循环（等价于 while(1)） // ... }
